using System;using System.IO;
public static class SourceShadeTests87 {
 static void Assert(bool b,string why){if(!b)throw new Exception(why);}
 static SourceShade87.Input Fixture(){return new SourceShade87.Input{sourceContract="original-model/image/UV/policy",levels=3,sourceMask=new[]{true,true,true,false},support=new[]{1,2,2,0},sourceRGBKey=new[]{0xFEDCC0,0x5078A0,0xFEDCC0,0},colourAddress=new[]{0,1,0,-1},finiteLinearRGBA=new[]{.1f,.05f,.025f,1f,.4f,.2f,.1f,1f,.8f,.7f,.6f,1f,.02f,.04f,.08f,1f,.1f,.2f,.4f,1f,.3f,.5f,.9f,1f}};}
 static SourceShade87.Packet Packet(){return new SourceShade87.Packet{sourceContract="original-model/image/UV/policy",sourceId="real-frame/sourceA",shadeSourceId="real-frame/sourceA",frame=101,shadeFrame=101,currentVisibleFace=new[]{true,true,true,false},sourceTexel=new[]{0,1,2,-1},selectedQ=new[]{.5f,1f,.5f,0f},currentLinearRGBA=new[]{.31f,.3f,.29f,.73f,.61f,.6f,.59f,.83f,.51f,.5f,.49f,.93f,.11f,.12f,.13f,.43f}};}
 public static void Main(string[] args){
  int checks=0;float[] output;string reason;var input=Fixture();var consumer=new SourceShade87(input);var packet=Packet();Assert(consumer.Ready&&consumer.TryCompose(packet,out output,out reason),"complete packet");consumer.TryCompose(packet,out output,out reason);
  Assert(output[0]==.4f&&output[1]==.2f&&output[2]==.1f&&output[4]==.3f&&output[5]==.5f&&output[6]==.9f,"two independent original source families, direct LUT");checks++;
  for(int i=0;i<4;i++)Assert(output[4*i+3]==packet.currentLinearRGBA[4*i+3],"alpha preserved");checks++;
  for(int j=0;j<4;j++)Assert(output[12+j]==packet.currentLinearRGBA[12+j],"nonface/hair untouched");checks++;
  for(int j=0;j<3;j++)Assert(output[j]==output[8+j],"support IDs do not change same source colour");checks++;
  // q==old q still performs the direct lookup; there is no old==q bypass.
  packet.currentLinearRGBA[0]=.913f;consumer.TryCompose(packet,out output,out reason);Assert(output[0]==.4f,"same Q must still pass LUT");checks++;
  foreach(int code in new[]{0,1,2,3,4}){packet=Packet();if(code==0)packet.shadeFrame--;if(code==1)packet.shadeSourceId="other-source";if(code==2)packet.sourceTexel[0]=3;if(code==3)packet.selectedQ[0]=.49f;if(code==4)packet.sourceContract="other-model";Assert(!consumer.TryCompose(packet,out output,out reason)&&output==null,"atomic packet rejection");checks++;}
  input=Fixture();input.colourAddress[2]=-1;consumer=new SourceShade87(input);Assert(!consumer.Ready&&consumer.unassignedSourceTexels==1&&!consumer.TryCompose(Packet(),out output,out reason)&&output==null,"partial LUT output prohibited");checks++;
  input=Fixture();input.colourAddress[2]=1;try{new SourceShade87(input);throw new Exception("same RGB material/region anchor accepted");}catch(ArgumentException){checks++;}
  input=Fixture();consumer=new SourceShade87(input);input.colourAddress[0]=1;input.finiteLinearRGBA[4]=.99f;consumer.TryCompose(Packet(),out output,out reason);Assert(output[0]==.4f,"immutable owned input copies");checks++;
  Console.WriteLine("checks="+checks);
  if(args.Length>=2){using(var r=new BinaryReader(File.OpenRead(args[0])))using(var w=new BinaryWriter(File.Create(args[1]))){int n=r.ReadInt32(),families=r.ReadInt32(),levels=r.ReadInt32();var a=new SourceShade87.Input{sourceContract=r.ReadString(),sourceMask=new bool[n],support=new int[n],sourceRGBKey=new int[n],colourAddress=new int[n],levels=levels,finiteLinearRGBA=new float[4*families*levels]};for(int i=0;i<n;i++){a.sourceMask[i]=r.ReadBoolean();a.support[i]=r.ReadInt32();a.sourceRGBKey[i]=r.ReadInt32();a.colourAddress[i]=r.ReadInt32();}for(int i=0;i<a.finiteLinearRGBA.Length;i++)a.finiteLinearRGBA[i]=r.ReadSingle();var c=new SourceShade87(a);w.Write(c.Ready);w.Write(c.sourceTexels);w.Write(c.unassignedSourceTexels);int frames=r.ReadInt32();w.Write(frames);for(int f=0;f<frames;f++){int frame=r.ReadInt32(),count=r.ReadInt32();string sid=r.ReadString();var p=new SourceShade87.Packet{sourceContract=a.sourceContract,sourceId=sid,shadeSourceId=sid,frame=frame,shadeFrame=frame,currentVisibleFace=new bool[count],sourceTexel=new int[count],selectedQ=new float[count],currentLinearRGBA=new float[4*count]};for(int i=0;i<count;i++){p.currentVisibleFace[i]=r.ReadBoolean();p.sourceTexel[i]=r.ReadInt32();p.selectedQ[i]=r.ReadSingle();for(int j=0;j<4;j++)p.currentLinearRGBA[4*i+j]=r.ReadSingle();}bool ok=c.TryCompose(p,out output,out reason);w.Write(ok);w.Write(output!=null);w.Write(reason??"");if(args.Length==3&&args[2]=="--rgb"&&output!=null){w.Write(output.Length);foreach(float v in output)w.Write(v);}}Assert(r.BaseStream.Position==r.BaseStream.Length,"trailing actual fixture");}}
 }
}
